/**
 * HYD Runners shared contracts.
 *
 * Single source of truth for the entities, identifiers, date formats and API
 * envelopes shared by every feature (and, later, the Expo app). Each entity is
 * a Zod schema plus its inferred TypeScript type, so the same definition
 * validates request bodies, AI output and database rows.
 *
 * Owned by the lead. Do not redefine these entities inside a feature folder,
 * and do not edit this file without agreement in a PR labelled `contracts`
 * (see CONTRIBUTING.md). Conventions are explained in docs/CONTRACTS.md.
 */
import { z } from "zod";

// ---------------------------------------------------------------------------
// Primitives and formats
// ---------------------------------------------------------------------------

/** Every identifier is a UUID string. User ids equal Supabase `auth.users.id`. */
export const Id = z.uuid();
export type Id = z.infer<typeof Id>;

/** Instant in time, ISO 8601 with offset, e.g. `2026-10-14T01:30:00Z`. Stored as UTC `timestamptz`. */
export const IsoDateTime = z.iso.datetime({ offset: true });
export type IsoDateTime = z.infer<typeof IsoDateTime>;

/** Calendar date without time, `YYYY-MM-DD`, interpreted in the user's timezone. */
export const IsoDate = z.iso.date();
export type IsoDate = z.infer<typeof IsoDate>;

/** Wall-clock time, 24-hour `HH:mm`, interpreted in the user's timezone. */
export const LocalTime = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/, "Expected HH:mm (24-hour)");
export type LocalTime = z.infer<typeof LocalTime>;

/** ISO weekday: 1 = Monday … 7 = Sunday. */
export const Weekday = z.number().int().min(1).max(7);
export type Weekday = z.infer<typeof Weekday>;

/** IANA timezone name. India has no DST, so the default is safe for local wall-clock maths. */
export const DEFAULT_TIMEZONE = "Asia/Kolkata";
export const Timezone = z.string().min(1).default(DEFAULT_TIMEZONE);

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

/** Mirrors the `public.app_role` Postgres enum. */
export const Role = z.enum(["runner", "coach", "mentor", "programme_manager", "admin"]);
export type Role = z.infer<typeof Role>;

export const STAFF_ROLES = ["coach", "mentor", "programme_manager", "admin"] as const satisfies readonly Role[];

/** Mirrors `public.fitness_level`. */
export const FitnessLevel = z.enum(["new_to_running", "returning", "regular"]);
export type FitnessLevel = z.infer<typeof FitnessLevel>;

/** The two overlapping problems the product solves. Mirrors `public.primary_need`. */
export const PrimaryNeed = z.enum(["consistency", "schedule_conflicts", "both"]);
export type PrimaryNeed = z.infer<typeof PrimaryNeed>;

export const UserProfile = z.object({
  id: Id,
  displayName: z.string().min(1).max(60),
  avatarPath: z.string().nullable(),
  fitnessLevel: FitnessLevel.nullable(),
  primaryNeed: PrimaryNeed.nullable(),
  timezone: z.string(),
  roles: z.array(Role).min(1),
  onboardedAt: IsoDateTime.nullable(),
  createdAt: IsoDateTime,
});
export type UserProfile = z.infer<typeof UserProfile>;

export const FitnessGoal = z.enum([
  "build_habit",
  "first_5k",
  "run_without_stopping",
  "get_stronger",
  "return_after_break",
]);
export type FitnessGoal = z.infer<typeof FitnessGoal>;

export const TimeOfDay = z.enum(["early_morning", "morning", "afternoon", "evening", "night"]);
export type TimeOfDay = z.infer<typeof TimeOfDay>;

export const UserPreferences = z.object({
  userId: Id,
  goal: FitnessGoal,
  /** Days the runner would like to train. */
  preferredDays: z.array(Weekday).max(7),
  preferredTimesOfDay: z.array(TimeOfDay).max(5),
  sessionsPerWeek: z.number().int().min(1).max(7),
  maxSessionMinutes: z.number().int().min(10).max(180),
  timezone: Timezone,
  remindersEnabled: z.boolean(),
});
export type UserPreferences = z.infer<typeof UserPreferences>;

// ---------------------------------------------------------------------------
// Scheduling
// ---------------------------------------------------------------------------

export const AvailabilityKind = z.enum(["busy", "free"]);
export const AvailabilitySource = z.enum(["manual", "ai", "text_parser"]);

/** Recurring weekly block in the user's local time (not a dated instant). */
export const AvailabilityBlock = z
  .object({
    id: Id,
    userId: Id,
    weekday: Weekday,
    startTime: LocalTime,
    endTime: LocalTime,
    kind: AvailabilityKind,
    label: z.string().max(80).nullable(),
    source: AvailabilitySource,
    sourceUploadId: Id.nullable(),
    /** 0–1 for extracted blocks; null for manual entries. */
    confidence: z.number().min(0).max(1).nullable(),
  })
  .refine((b) => b.endTime > b.startTime, { message: "endTime must be after startTime", path: ["endTime"] });
export type AvailabilityBlock = z.infer<typeof AvailabilityBlock>;

export const TimetableUploadStatus = z.enum(["uploaded", "processing", "needs_review", "confirmed", "failed"]);
export type TimetableUploadStatus = z.infer<typeof TimetableUploadStatus>;

export const TimetableUpload = z.object({
  id: Id,
  userId: Id,
  /** Path inside the private `timetables` bucket: `{userId}/{uuid}.{ext}`. */
  storagePath: z.string(),
  mimeType: z.enum(["application/pdf", "image/png", "image/jpeg", "image/webp"]),
  status: TimetableUploadStatus,
  method: AvailabilitySource.nullable(),
  errorCode: z.string().nullable(),
  createdAt: IsoDateTime,
});
export type TimetableUpload = z.infer<typeof TimetableUpload>;

/**
 * Output contract for any timetable extractor (LLM or deterministic parser).
 * The scheduler depends on this shape, never on a specific provider.
 */
export const ExtractedTimetable = z.object({
  blocks: z.array(
    z.object({
      weekday: Weekday,
      startTime: LocalTime,
      endTime: LocalTime,
      label: z.string().max(80).nullable(),
      confidence: z.number().min(0).max(1),
    }),
  ),
  timezone: z.string().default(DEFAULT_TIMEZONE),
  notes: z.string().max(500).nullable(),
});
export type ExtractedTimetable = z.infer<typeof ExtractedTimetable>;

export const WorkoutType = z.enum([
  "run",
  "walk_run",
  "walk",
  "strength",
  "conditioning",
  "mobility",
  "cross_training",
  "rest",
]);
export type WorkoutType = z.infer<typeof WorkoutType>;

export const PlannedWorkoutStatus = z.enum(["planned", "completed", "missed", "rescheduled", "skipped"]);
export type PlannedWorkoutStatus = z.infer<typeof PlannedWorkoutStatus>;

export const PlannedWorkout = z.object({
  id: Id,
  userId: Id,
  enrollmentId: Id.nullable(),
  programmeSessionId: Id.nullable(),
  title: z.string().min(1).max(120),
  workoutType: WorkoutType,
  startsAt: IsoDateTime,
  durationMinutes: z.number().int().min(5).max(300),
  status: PlannedWorkoutStatus,
  /** Who placed it: the deterministic scheduler, the runner, or a coach. */
  plannedBy: z.enum(["scheduler", "runner", "coach"]),
});
export type PlannedWorkout = z.infer<typeof PlannedWorkout>;

/** Pure input to the scheduling algorithm (src/features/scheduler). Provider-independent. */
export const SchedulerInput = z.object({
  weekStart: IsoDate,
  timezone: z.string(),
  availability: z.array(AvailabilityBlock),
  preferences: UserPreferences,
  sessionsToPlace: z.array(
    z.object({
      programmeSessionId: Id.nullable(),
      title: z.string(),
      workoutType: WorkoutType,
      durationMinutes: z.number().int().positive(),
    }),
  ),
  existing: z.array(PlannedWorkout),
});
export type SchedulerInput = z.infer<typeof SchedulerInput>;

export const SchedulerResult = z.object({
  placed: z.array(PlannedWorkout.omit({ id: true, status: true })),
  unplaced: z.array(z.object({ title: z.string(), reason: z.string() })),
});
export type SchedulerResult = z.infer<typeof SchedulerResult>;

// ---------------------------------------------------------------------------
// Workouts and programmes
// ---------------------------------------------------------------------------

export const CompletedWorkout = z.object({
  id: Id,
  userId: Id,
  plannedWorkoutId: Id.nullable(),
  workoutType: WorkoutType,
  startedAt: IsoDateTime,
  durationSeconds: z
    .number()
    .int()
    .min(60)
    .max(6 * 60 * 60),
  distanceMeters: z.number().int().min(0).max(100_000).nullable(),
  /** Rate of perceived exertion, 1 (very easy) – 10 (maximal). */
  perceivedEffort: z.number().int().min(1).max(10).nullable(),
  locationId: Id.nullable(),
  notes: z.string().max(1000).nullable(),
  createdAt: IsoDateTime,
});
export type CompletedWorkout = z.infer<typeof CompletedWorkout>;

export const ProgrammeKind = z.enum(["couch_to_5k", "strength_conditioning", "custom"]);
export const ProgrammeLevel = z.enum(["beginner", "intermediate", "advanced"]);

export const WorkoutBlock = z.object({
  kind: z.enum(["warm_up", "run", "walk", "strength", "conditioning", "rest", "cool_down"]),
  durationSeconds: z.number().int().positive().nullable(),
  sets: z.number().int().positive().nullable(),
  reps: z.number().int().positive().nullable(),
  repeat: z.number().int().positive().default(1),
  notes: z.string().max(200).nullable(),
});
export type WorkoutBlock = z.infer<typeof WorkoutBlock>;

export const ProgrammeSession = z.object({
  id: Id,
  programmeId: Id,
  week: z.number().int().min(1),
  day: z.number().int().min(1).max(7),
  title: z.string().min(1).max(120),
  workoutType: WorkoutType,
  estimatedMinutes: z.number().int().positive(),
  blocks: z.array(WorkoutBlock),
});
export type ProgrammeSession = z.infer<typeof ProgrammeSession>;

export const TrainingProgramme = z.object({
  id: Id,
  slug: z.string().regex(/^[a-z0-9-]+$/),
  title: z.string().min(1).max(120),
  summary: z.string().max(500),
  kind: ProgrammeKind,
  level: ProgrammeLevel,
  durationWeeks: z.number().int().min(1).max(52),
  sessionsPerWeek: z.number().int().min(1).max(7),
  published: z.boolean(),
  ownerId: Id.nullable(),
});
export type TrainingProgramme = z.infer<typeof TrainingProgramme>;

// ---------------------------------------------------------------------------
// Community: locations, events, feedback, announcements
// ---------------------------------------------------------------------------

/** Mirrors `public.location_kind`. */
export const LocationKind = z.enum(["park", "track", "lake_loop", "gym", "trail", "other"]);
export type LocationKind = z.infer<typeof LocationKind>;

export const Location = z.object({
  id: Id,
  name: z.string().min(1).max(120),
  kind: LocationKind,
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180),
  address: z.string().nullable(),
  /** Unverified rows (e.g. seed data) must be labelled as such in the UI. */
  verified: z.boolean(),
});
export type Location = z.infer<typeof Location>;

/** Mirrors `public.event_status`. */
export const EventStatus = z.enum(["draft", "published", "cancelled"]);
export type EventStatus = z.infer<typeof EventStatus>;

export const CommunityEvent = z
  .object({
    id: Id,
    title: z.string().min(1).max(120),
    description: z.string(),
    startsAt: IsoDateTime,
    endsAt: IsoDateTime,
    locationId: Id.nullable(),
    capacity: z.number().int().positive().nullable(),
    status: EventStatus,
    createdBy: Id.nullable(),
  })
  .refine((e) => e.endsAt > e.startsAt, { message: "endsAt must be after startsAt", path: ["endsAt"] });
export type CommunityEvent = z.infer<typeof CommunityEvent>;

export const FeedbackTarget = z.enum(["session", "programme", "event", "coach", "app"]);
export const FeedbackStatus = z.enum(["new", "acknowledged", "resolved"]);

export const RunnerFeedback = z.object({
  id: Id,
  userId: Id,
  target: FeedbackTarget,
  targetId: Id.nullable(),
  rating: z.number().int().min(1).max(5).nullable(),
  body: z.string().min(1).max(2000),
  status: FeedbackStatus,
  createdAt: IsoDateTime,
});
export type RunnerFeedback = z.infer<typeof RunnerFeedback>;

export const AnnouncementAudience = z.enum(["everyone", "programme", "coach_group"]);

export const Announcement = z.object({
  id: Id,
  authorId: Id,
  audience: AnnouncementAudience,
  /** Programme or group id when audience is not `everyone`. */
  audienceId: Id.nullable(),
  title: z.string().min(1).max(120),
  body: z.string().min(1).max(5000),
  publishAt: IsoDateTime,
});
export type Announcement = z.infer<typeof Announcement>;

// ---------------------------------------------------------------------------
// Gamification
// ---------------------------------------------------------------------------

export const XpReason = z.enum([
  "workout_completed",
  "planned_workout_on_time",
  "streak_milestone",
  "badge_earned",
  "event_attended",
  "feedback_submitted",
  "admin_adjustment",
]);
export type XpReason = z.infer<typeof XpReason>;

/**
 * Append-only ledger entry. Totals are always derived from the ledger and are
 * only ever written server-side (trigger or security-definer function).
 */
export const XpTransaction = z.object({
  id: Id,
  userId: Id,
  deltaXp: z.number().int(),
  deltaCoins: z.number().int(),
  reason: XpReason,
  /** Table and row that caused the award, e.g. `workout_logs` + id. Unique per (reason, refId). */
  refTable: z.string().nullable(),
  refId: Id.nullable(),
  createdAt: IsoDateTime,
});
export type XpTransaction = z.infer<typeof XpTransaction>;

export const EarnedBadge = z.object({
  code: z.string(),
  title: z.string(),
  earnedAt: IsoDateTime,
});
export type EarnedBadge = z.infer<typeof EarnedBadge>;

export const AchievementSummary = z.object({
  userId: Id,
  totalXp: z.number().int().min(0),
  coins: z.number().int().min(0),
  level: z.number().int().min(1),
  xpIntoLevel: z.number().int().min(0),
  xpForNextLevel: z.number().int().positive(),
  currentStreakDays: z.number().int().min(0),
  longestStreakDays: z.number().int().min(0),
  characterStage: z.number().int().min(1),
  recentBadges: z.array(EarnedBadge),
});
export type AchievementSummary = z.infer<typeof AchievementSummary>;

// ---------------------------------------------------------------------------
// Reports
// ---------------------------------------------------------------------------

export const ReportPeriod = z.enum(["week", "month", "year"]);
export type ReportPeriod = z.infer<typeof ReportPeriod>;

export const ActivityReport = z.object({
  userId: Id,
  period: ReportPeriod,
  periodStart: IsoDate,
  plannedSessions: z.number().int().min(0),
  completedSessions: z.number().int().min(0),
  totalDurationSeconds: z.number().int().min(0),
  totalDistanceMeters: z.number().int().min(0),
  xpEarned: z.number().int(),
  longestStreakDays: z.number().int().min(0),
});
export type ActivityReport = z.infer<typeof ActivityReport>;

// ---------------------------------------------------------------------------
// API envelope and errors (all /api/v1 responses)
// ---------------------------------------------------------------------------

export const ErrorCode = z.enum([
  "bad_request",
  "validation_failed",
  "unauthenticated",
  "forbidden",
  "not_found",
  "conflict",
  "rate_limited",
  "payload_too_large",
  "unsupported_media_type",
  "ai_unavailable",
  "not_implemented",
  "internal_error",
]);
export type ErrorCode = z.infer<typeof ErrorCode>;

/** HTTP status for each error code. Route handlers must use this table. */
export const ERROR_STATUS: Record<ErrorCode, number> = {
  bad_request: 400,
  validation_failed: 422,
  unauthenticated: 401,
  forbidden: 403,
  not_found: 404,
  conflict: 409,
  rate_limited: 429,
  payload_too_large: 413,
  unsupported_media_type: 415,
  ai_unavailable: 503,
  not_implemented: 501,
  internal_error: 500,
};

export const ApiError = z.object({
  error: z.object({
    code: ErrorCode,
    /** Human-readable, safe to show to the runner. Never contains stack traces or SQL. */
    message: z.string(),
    /** Optional field-level details, e.g. flattened Zod issues. */
    details: z.unknown().optional(),
  }),
});
export type ApiError = z.infer<typeof ApiError>;

export type PageMeta = { nextCursor: string | null };

export type ApiSuccess<T> = { data: T; meta?: PageMeta };
export type ApiResponse<T> = ApiSuccess<T> | ApiError;

export const apiSuccess = <T extends z.ZodType>(data: T) =>
  z.object({ data, meta: z.object({ nextCursor: z.string().nullable() }).optional() });

export const API_VERSION = "v1" as const;
